class DirView {                            // one wrapper per wrapped object
  std::shared_ptr<MemDir> target_;
  std::shared_ptr<Membrane> m_;
public:
  File open(std::string_view p) {
    if (m_->revoked()) throw std::runtime_error("revoked");
    return File{DirView{m_->wrap(target_->open(p)), m_}};  // wrap the way out
  }
};

